function update(x){
  const h = hash32(x); // 32-bit hash
  const i = h >>> (32 - mLog); // top bits
  const w = h & ((1 << (32 - mLog)) - 1);
  const r = 1 + ctz(~w); // position of first 1 in remaining bits
  registers[i] = Math.max(registers[i], r);
}
function estimate(){
  const sum = registers.reduce((a,b)=> a + Math.pow(2, -b), 0);
  return alpha_m * m * m / sum;
